def solve(grid, start, goal):
    from collections import deque

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(grid), len(grid[0])
    visited = set()
    path = []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited

    def backtrack(r, c):
        if (r, c) == start:
            path.append((r, c))
            return True
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                path.append((nr, nc))
                if backtrack(nr, nc):
                    return True
                path.pop()
        return False

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal:
        return [start]

    visited.add(start)
    if backtrack(goal[0], goal[1]):
        return path[::-1]
    else:
        return []
```

