def solve(n, edges, s, t):
    from collections import defaultdict

    if s == t:
        return 0

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path with negative weights
    # Since n <= 100, it's efficient enough

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in graph[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
```

